contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1);
        address bob = address(0x2);

        // First call: Alice sends 0 ether (reference reverts, bug succeeds and sets pastBlockTime)
        vm.deal(address(this), 100 ether);
        vm.deal(alice, 0 ether);
        vm.prank(alice);
        (bool success1,) = address(c).call{value: 0 ether}("");

        // Warp to same block (block.number unchanged) to ensure timing condition
        // Second call: Bob sends 10 ether
        vm.deal(bob, 10 ether);
        vm.prank(bob);
        bool success2;
        // Use a try-catch to capture revert
        try c.call{value: 10 ether}("") { success2 = true; } catch { success2 = false; }

        // The reference contract reverts on the first call (success1 = false) and pastBlockTime remains 0,
        // so the second call succeeds (success2 = true). The buggy contract succeeds on first call (success1 = true),
        // sets pastBlockTime to block.timestamp+1, causing the second call to revert (success2 = false).
        // Assert that the second call succeeds on the reference (we expect true), but on the buggy it fails (false).
        assertTrue(success2 == true);
    }
}

