pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // First call: block.timestamp=1, block.number=1, msg.value=10 ether
        // Reference: timestamp check fails (1 > 0 is true), so updates pastBlockTime to 2
        // Buggy: unconditionally updates pastBlockTime to 2
        vm.warp(1);
        vm.roll(1);
        vm.deal(address(this), 10 ether);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);
        // After first call, both contracts have pastBlockTime == 2

        // Second call: block.timestamp=100, block.number=15, msg.value=10 ether
        // Reference: now pastBlockTime=2, timestamp 100 > 2 is true, so updates pastBlockTime to 101
        // Buggy: unconditionally updates pastBlockTime to 101
        vm.warp(100);
        vm.roll(15);
        vm.deal(address(this), 10 ether);
        (bool ok2,) = address(c).call{value: 10 ether}("");
        assertTrue(ok2);

        // After both calls, pastBlockTime should be 101 for both? Wait, need to check carefully.
        // Actually the difference: first call both set to 2. Second call both set to 101.
        // So after two calls, pastBlockTime is 101 for both. That doesn't diverge.
        // Let's try a different approach: single call where timestamp check fails on reference.
        // Single call at block.timestamp=100, block.number=15, msg.value=10 ether:
        // Reference: pastBlockTime=0 initially, 100 > 0 is true, so updates to 101.
        // Buggy: unconditionally updates to 101. Same.
        // The only way to diverge is when timestamp <= pastBlockTime.
        // Set pastBlockTime to some high value first, then call with lower timestamp.
        // But we can't set pastBlockTime directly; we must go through the contract.
        // First call at timestamp=100, block.number=1 (no if) sets pastBlockTime to 101.
        // Second call at timestamp=50, block.number=15: reference fails (50 > 101 false), keeps 101; buggy sets to 51.

        // Reset: deploy new contract
        c = new C();

        // First call: timestamp=100, block.number=1, value=10 ether
        vm.warp(100);
        vm.roll(1);
        vm.deal(address(this), 10 ether);
        (bool ok3,) = address(c).call{value: 10 ether}("");
        assertTrue(ok3);
        // Both contracts have pastBlockTime=101 (since 100>0)

        // Second call: timestamp=50, block.number=15, value=10 ether
        vm.warp(50);
        vm.roll(15);
        vm.deal(address(this), 10 ether);
        (bool ok4,) = address(c).call{value: 10 ether}("");
        assertTrue(ok4);
        // Reference: 50 > 101 is false, so pastBlockTime stays 101
        // Buggy: unconditionally sets pastBlockTime = 51

        // Assert: reference has 101, buggy has 51
        assertTrue(c.pastBlockTime() == 101);
    }
}

