        (bool ok2, ) = address(c).call{value: 10 ether}("");
        // Reference: ok2 == false (revert), bug: ok2 == true
        // So assert that the last call reverted (i.e., the contract behaved like the reference)
        assertTrue(!ok2, "Second call should have reverted on reference");
    }
